import { describe, it, expect } from 'vitest';
import { Buffer } from 'node:buffer';
import {
    assToBlocks,
    cleanAssText,
    decodeAssBuffer,
    getAssField,
    parseAssContent,
    parseAssTime,
} from '../../server/utils/ass';

const V4_PLUS_ASS = String.raw`[Script Info]
; Script generated by Aegisub
Title: 测试字幕
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H009C46A5,&H00000000,-1,0,0,0,100,100,0,0,1,3,0,2,0,0,0,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Comment: 0,0:00:00.00,0:00:01.00,Default,,0,0,0,,这是一行注释
Dialogue: 0,0:00:05.00,0:00:10.00,Default,,0,0,0,,{\fad(200,200)\pos(960,1020)}第二句,带逗号
Dialogue: 2,0:00:01.00,0:00:03.00,Default,,0,0,0,,{\an8}第一句\N换行
Dialogue: 0,0:00:20.00,0:00:20.00,Default,,0,0,0,,零长度事件
`;

const SSA_V4_ASS = String.raw`[Script Info]
ScriptType: v4.00

[V4 Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, TertiaryColour, BackColour, Bold, Italic, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, AlphaLevel, Encoding
Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H009C46A5,&H00000000,-1,0,1,3,0,2,0,0,0,1

[Events]
Format: Marked, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: Marked=0,0:00:01.00,0:00:02.50,Default,,0,0,0,,SSA 第一句
Dialogue: Marked=1,0:00:03.00,0:00:04.25,Default,,0,0,0,,SSA 第二句
`;

function encodeUtf16BE(text: string): Buffer {
    const littleEndian = Buffer.from(text, 'utf16le');
    const bigEndian = Buffer.alloc(littleEndian.length);
    for (let index = 0; index < littleEndian.length; index += 2) {
        bigEndian[index] = littleEndian[index + 1] ?? 0;
        bigEndian[index + 1] = littleEndian[index] ?? 0;
    }
    return bigEndian;
}

describe('decodeAssBuffer 编码识别', () => {
    const content = '[Script Info]\nTitle: 你好，字幕\n';

    it('解码无 BOM 的 UTF-8', () => {
        expect(decodeAssBuffer(Buffer.from(content, 'utf8'))).toBe(content);
    });

    it('解码 UTF-8 BOM 并去掉 BOM 字符', () => {
        const buffer = Buffer.concat([
            Buffer.from([0xef, 0xbb, 0xbf]),
            Buffer.from(content, 'utf8'),
        ]);
        const decoded = decodeAssBuffer(buffer);
        expect(decoded).toBe(content);
        expect(decoded.startsWith('\uFEFF')).toBe(false);
    });

    it('解码 UTF-16LE BOM', () => {
        const buffer = Buffer.concat([Buffer.from([0xff, 0xfe]), Buffer.from(content, 'utf16le')]);
        expect(decodeAssBuffer(buffer)).toBe(content);
    });

    it('解码 UTF-16BE BOM', () => {
        const buffer = Buffer.concat([Buffer.from([0xfe, 0xff]), encodeUtf16BE(content)]);
        expect(decodeAssBuffer(buffer)).toBe(content);
    });

    it('无 BOM 但带 UTF-16LE 特征时按 UTF-16LE 解码', () => {
        expect(decodeAssBuffer(Buffer.from(content, 'utf16le'))).toBe(content);
    });

    it('非 UTF-8 时回退 GB18030/GBK 解码', () => {
        // GBK: 你好 = C4 E3 BA C3
        const buffer = Buffer.concat([
            Buffer.from('[Script Info]\nTitle: ', 'utf8'),
            Buffer.from([0xc4, 0xe3, 0xba, 0xc3]),
        ]);
        expect(decodeAssBuffer(buffer)).toBe('[Script Info]\nTitle: 你好');
    });

    it('空 Buffer 返回空字符串', () => {
        expect(decodeAssBuffer(Buffer.alloc(0))).toBe('');
    });
});

describe('parseAssContent ASS v4.00+', () => {
    const parsed = parseAssContent(V4_PLUS_ASS);

    it('解析 [Script Info] 键值', () => {
        expect(parsed.scriptInfo.Title).toBe('测试字幕');
        expect(parsed.scriptInfo.ScriptType).toBe('v4.00+');
        expect(parsed.scriptInfo.PlayResX).toBe('1920');
    });

    it('解析 [V4+ Styles] 的 Format 与 Style', () => {
        expect(parsed.styleSection).toBe('V4+ Styles');
        expect(parsed.styleFormat).toContain('OutlineColour');
        expect(parsed.styles).toHaveLength(1);
        expect(parsed.styles[0]!.name).toBe('Default');
        expect(getAssField(parsed.styles[0]!.fields, 'OutlineColour')).toBe('&H009C46A5');
        expect(getAssField(parsed.styles[0]!.fields, 'Fontname')).toBe('Arial');
    });

    it('解析 Dialogue 与 Comment，未跳过合法事件', () => {
        expect(parsed.events).toHaveLength(3);
        expect(parsed.comments).toHaveLength(1);
        expect(parsed.comments[0]!.type).toBe('Comment');
        expect(parsed.events[0]!.startTime).toBe(5);
        expect(parsed.events[0]!.endTime).toBe(10);
    });

    it('清理 override tags、\\N 换行与文本中的逗号', () => {
        const firstEvent = parsed.events.find((event) => event.startTime === 5)!;
        expect(firstEvent.text).toBe('第二句,带逗号');

        const secondEvent = parsed.events.find((event) => event.startTime === 1)!;
        expect(secondEvent.text).toBe('第一句 换行');
    });
});

describe('parseAssContent SSA v4', () => {
    const parsed = parseAssContent(SSA_V4_ASS);

    it('解析 [V4 Styles] 的 TertiaryColour', () => {
        expect(parsed.styleSection).toBe('V4 Styles');
        expect(parsed.styles).toHaveLength(1);
        expect(getAssField(parsed.styles[0]!.fields, 'TertiaryColour')).toBe('&H009C46A5');
    });

    it('按 Marked 字段映射轨道（>0 为 2）', () => {
        const blocks = assToBlocks(parsed, 'ssa-song');
        expect(blocks).toHaveLength(2);
        expect(blocks[0]!.track).toBe(1);
        expect(blocks[1]!.track).toBe(2);
        expect(blocks[0]!.text).toBe('SSA 第一句');
        expect(blocks[1]!.startTime).toBe(3);
        expect(blocks[1]!.endTime).toBe(4.25);
    });
});

describe('parseAssContent 容错能力', () => {
    it('段名与 Format/Style/Dialogue 关键字大小写不敏感', () => {
        const content = String.raw`[script info]
scripttype: v4.00+

[v4+ styles]
format: name, fontname, fontsize, primarycolour, secondarycolour, outlinecolour
style: Default,MyFont,40,&H00FFFFFF,&H000000FF,&H00123456

[events]
format: layer, start, end, style, name, margin l, margin r, margin v, effect, text
Dialogue: 0,0:00:01.50,0:00:02.50,Default,,0,0,0,,小写测试
`;
        const parsed = parseAssContent(content);
        expect(parsed.scriptInfo.scripttype).toBe('v4.00+');
        expect(parsed.styles[0]!.format).toEqual([
            'Name',
            'Fontname',
            'Fontsize',
            'PrimaryColour',
            'SecondaryColour',
            'OutlineColour',
        ]);
        expect(getAssField(parsed.styles[0]!.fields, 'outlinecolour')).toBe('&H00123456');
        expect(parsed.events[0]!.startTime).toBe(1.5);
        expect(parsed.events[0]!.text).toBe('小写测试');
    });

    it('Events/Styles 的 Format 字段顺序任意时按字段名取值', () => {
        const content = String.raw`[Script Info]
ScriptType: v4.00+

[V4+ Styles]
Format: Name, OutlineColour, Fontname, Fontsize, PrimaryColour, SecondaryColour, BackColour
Style: Shuffled,&H00112233,MyFont,40,&H00FFFFFF,&H000000FF,&H00000000

[Events]
Format: Start, End, Layer, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0:00:02.00,0:00:03.50,1,Shuffled,,0,0,0,,乱序字段,文本
`;
        const parsed = parseAssContent(content);
        expect(getAssField(parsed.styles[0]!.fields, 'OutlineColour')).toBe('&H00112233');
        expect(getAssField(parsed.styles[0]!.fields, 'Fontname')).toBe('MyFont');
        expect(parsed.events[0]!.startTime).toBe(2);
        expect(parsed.events[0]!.endTime).toBe(3.5);
        expect(parsed.events[0]!.text).toBe('乱序字段,文本');

        const blocks = assToBlocks(parsed, 'shuffled');
        expect(blocks[0]!.track).toBe(2);
    });

    it('时间非法的事件被跳过', () => {
        const content = String.raw`[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,abc,0:00:01.00,Default,,0,0,0,,非法开始
Dialogue: 0,0:00:01.00,bad,Default,,0,0,0,,非法结束
Dialogue: 0,0:00:61.00,0:00:02.00,Default,,0,0,0,,秒超范围
Dialogue: 0,0:00:05.00,0:00:06.00,Default,,0,0,0,,合法事件
Comment: 0,oops,0:00:06.00,Default,,0,0,0,,非法注释
`;
        const parsed = parseAssContent(content);
        expect(parsed.events).toHaveLength(1);
        expect(parsed.events[0]!.text).toBe('合法事件');
        expect(parsed.comments).toHaveLength(0);
    });

    it('忽略非 [Events] 段与注释行', () => {
        const content = String.raw`; 文件级注释
[Script Info]
; 段内注释
Title: 只读
[Aegisub Project Garbage]
Audio File: foo.mp4

[Events]
; 事件段注释
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,唯一事件
`;
        const parsed = parseAssContent(content);
        expect(parsed.events).toHaveLength(1);
        expect(parsed.scriptInfo.Title).toBe('只读');
        expect(parsed.scriptInfo['Audio File']).toBeUndefined();
    });

    it('兼容 CRLF 与 BOM', () => {
        const crlfContent = `\uFEFF[Script Info]\r\nScriptType: v4.00+\r\n\r\n[Events]\r\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\r\nDialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,CRLF 事件\r\n`;
        const parsed = parseAssContent(crlfContent);
        expect(parsed.scriptInfo.ScriptType).toBe('v4.00+');
        expect(parsed.events[0]!.text).toBe('CRLF 事件');
    });

    it('没有 Format 行时按默认字段解析', () => {
        const content = String.raw`[Events]
Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,无 Format
`;
        const parsed = parseAssContent(content);
        expect(parsed.events).toHaveLength(1);
        expect(parsed.events[0]!.text).toBe('无 Format');
    });

    it('空内容返回空结构', () => {
        const parsed = parseAssContent('');
        expect(parsed.events).toEqual([]);
        expect(parsed.comments).toEqual([]);
        expect(parsed.styles).toEqual([]);
        expect(parsed.scriptInfo).toEqual({});
        expect(parsed.styleSection).toBeNull();
        expect(parsed.eventFormat).toBeNull();
    });
});

describe('assToBlocks 时间轴转换', () => {
    const content = String.raw`[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:10.00,0:00:12.00,Default,,0,0,0,,第三句
Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,第一句
Dialogue: 0,0:00:05.00,0:00:06.00,Default,,0,0,0,,第二句
Dialogue: 0,0:00:07.00,0:00:08.00,Default,,0,0,0,,{}
Dialogue: 0,0:00:09.00,0:00:09.00,Default,,0,0,0,,零长度
Dialogue: 0,0:00:03.00,0:00:04.00,Default,,0,0,0,,A{\i1}B{\i0}C
`;
    const blocks = assToBlocks(parseAssContent(content), 'song');

    it('只保留 startTime < endTime 且文本非空的事件', () => {
        expect(blocks.map((block) => block.text)).toEqual(['第一句', 'ABC', '第二句', '第三句']);
    });

    it('按开始时间稳定排序并生成 id', () => {
        expect(blocks.map((block) => block.startTime)).toEqual([1, 3, 5, 10]);
        expect(blocks.map((block) => block.id)).toEqual(['song-1', 'song-2', 'song-3', 'song-4']);
    });

    it('默认 track 为 1', () => {
        expect(blocks.every((block) => block.track === 1)).toBe(true);
    });
});

describe('parseAssTime 时间解析', () => {
    it('解析 h:mm:ss.cc，兼容 1-3 位小数', () => {
        expect(parseAssTime('0:00:30.59')).toBe(30.59);
        expect(parseAssTime('0:01:05.2')).toBe(65.2);
        expect(parseAssTime('0:00:05')).toBe(5);
        expect(parseAssTime('1:02:03.456')).toBe(3723.456);
        expect(parseAssTime('00:00:00.00')).toBe(0);
    });

    it('非法时间返回 null', () => {
        expect(parseAssTime('abc')).toBeNull();
        expect(parseAssTime('0:00')).toBeNull();
        expect(parseAssTime('0:00:60.00')).toBeNull();
        expect(parseAssTime('0:61:00.00')).toBeNull();
        expect(parseAssTime('')).toBeNull();
        expect(parseAssTime(undefined)).toBeNull();
    });
});

describe('cleanAssText 文本清理', () => {
    it('去掉 override tags 并转换换行转义', () => {
        expect(cleanAssText(String.raw`{\fad(200,200)\pos(960,1020)}Hello\NWorld`)).toBe(
            'Hello World',
        );
        expect(cleanAssText(String.raw`A\nB\hC`)).toBe('A B C');
        expect(cleanAssText(String.raw`{\i1}前{\i0}中{\b1}后`)).toBe('前中后');
    });

    it('保留文本内部逗号与全角空格，去掉首尾空白', () => {
        expect(cleanAssText('  你好，世界　再见  ')).toBe('你好，世界　再见');
        expect(cleanAssText(String.raw`{\an8}带,逗号,文本`)).toBe('带,逗号,文本');
    });

    it('空文本清理后为空字符串', () => {
        expect(cleanAssText('')).toBe('');
        expect(cleanAssText(String.raw`{\pos(1,2)}`)).toBe('');
    });
});

describe('getAssField 字段读取', () => {
    it('大小写不敏感地读取字段', () => {
        const fields = { Start: '0:00:01.00', Text: '文本' };
        expect(getAssField(fields, 'start')).toBe('0:00:01.00');
        expect(getAssField(fields, 'TEXT')).toBe('文本');
        expect(getAssField(fields, 'End')).toBeUndefined();
    });
});
